visualizations.logic:
var tesseract = variables.tesseract;
var hierarchy = variables.hierarchy;
var id = variables.id;
var name = variables.name;
var years = variables.years;
var quarters = variables.quarters;

var time = "yearOption"// yearOption, quarterOption
var timeName = "السنوي"
var timeCut = time === "yearOption" ? "Year" : "Quarter"
var timeCutLabel = time === "yearOption" ? "Year" : "Quarter ID"

var translations = {
  title: {en: ("Evolution of the Number of Bank Branches in " + name + "<br /> <span class=\"subtitle\">(" + timeName + ")</span>"), 
           ar: (" التطوّر في عدد فروع البنوك في " + name + " <br /> <span class=\"subtitle\">(" + timeName + ")</span>")},
  quarter: {en: "Quarter", ar: "الربع"},
  year: {en: "Year", ar: "السنة"},
  banks: {en: "Bank Branches", ar: "عدد الفروع"},
}

var timeTooltip = time === "yearOption" ? ("" + (translations["year"][locale])) : ("" + (translations["quarter"][locale]))

var dataYear = tesseract + "/data.jsonrecords?" + hierarchy + "=" + id + "&cube=sama_bank_branches&drilldowns=Year,Province&measures=Bank+Branches&locale=" + locale
var dataQuarter = tesseract + "/data.jsonrecords?" + hierarchy + "=" + id + "&cube=sama_bank_branches&drilldowns=Quarter,Province&measures=Bank+Branches&locale=" + locale

return {
  data: [dataYear, dataQuarter],
  dataFormat: function (resp) {
    var dataYear = resp[0].data.map(function (d) { return Object.assign({}, d); });
    var dataQuarter = resp[1].data.map(function (d) { return Object.assign({}, d); });
    
    var dataYear_ = dataQuarter.filter(function (d) { return d["Quarter ID"].toString().slice(-1) === "4"; })
    dataYear_.forEach(function (d) {
      d["Year"] = (d["Quarter ID"].toString().slice(0,4)) * 1
    })
    
    var maxQuarter = libs.d3.max(dataQuarter, function (d) { return d["Quarter ID"]; }).toString().slice(-1)
    var maxYear = libs.d3.max(dataYear_, function (d) { return d["Year"]; })
    //const lastYear = maxQuarter !== 4 ? maxYear - 1 : maxYear
    var dataFinal = time === "yearOption" ? dataYear_.filter(function (d) { return d["Year"] <= maxYear; }) : dataQuarter

    return dataFinal;
  },
  viewDataFormat: function (resp) {
    var dataYear = resp[0].data;
    var dataQuarter = resp[1].data;
    
    var dataYear_ = dataQuarter.filter(function (d) { return d["Quarter ID"].toString().slice(-1) === "4"; })
    dataYear_.forEach(function (d) {
      d["Year"] = (d["Quarter ID"].toString().slice(0,4)) * 1
    })
    
    var dataFinal = time === "yearOption" ? dataYear_ : dataQuarter
    
    return dataFinal.map(function (d) {
      var obj;

      return (( obj = {}, obj[timeTooltip] = d[timeCut], obj[("" + (translations["banks"][locale]))] = d["Bank Branches"], obj ));
    })
  },
  lineLabels: true,
  shapeConfig: {
    Line: {
      label: function label(d) {
        var dataArray = this._filteredData
          	.filter(function (f) { return f["Province ID"] === d["Province ID"]; });
        var maxX = Math.max.apply(Math, dataArray.map(function (f) { return f[timeCutLabel]; }));			
        var maxData = dataArray
        	.find(function (f) { return f[timeCutLabel] === maxX; });
        
        return ("" + (formatters.commas(maxData["Bank Branches"])));
      },
    }
  },
  groupBy: ["Province ID"],
  label: function (d) { return String(d["Province"]); },
  title: ("" + (translations["title"][locale])), 
  time: timeCut,
  timeline: true,
  timelineConfig: {
    brushing: true,
    playButton: false
  },
  tooltipConfig: {
    tbody: [
      [timeTooltip, function (d) { return formatters.quarterTooltip(d[timeCut]); }],
      [("" + (translations["banks"][locale])), function (d) { return formatters.commas(d["Bank Branches"]); }]
    ]
  },
  type: "LinePlot",
  x: timeCut,
  xConfig: {
    title: time === "yearOption" ? years : quarters
  },
  y: "Bank Branches",
  yConfig: {
    title: ("" + (translations["banks"][locale])),
    tickFormat: function (d) { return formatters.commas(d); }
  }
};

var years = variables.years;
var selector = "rationalizeConsumption" // rationalizeConsumption, spendingEnergyEfficiency, efficiencyPractices, solarEnergyInterest

var drilldown = selector === "rationalizeConsumption" ? "Rationalize electricity consumption" : selector === "spendingEnergyEfficiency" ? "Spending money on new appliances" : selector === "solarEnergyInterest" ? "Response" : "Response Name"
var groupBy_ = selector === "rationalizeConsumption" ? "Rationalize electricity consumption" : selector === "spendingEnergyEfficiency" ? "Spending money on new appliances" : selector === "solarEnergyInterest" ? "Solar Energy Response" : "Response Name"

var translations = {
  title: {
    rationalizeConsumption: {en: ("Percentage of Households Interested in Rationalizing Electricity Consumption in Dwellings in " + (variables.name)), ar: ("نسبة الأسر المهتمة بترشيد استهلاك الكهرباء في المساكن في " + (variables.name))},
    efficiencyPractices: {en: ("Percentage of Households that Apply Energy Rationalization Instructions in the Use of Electrical Appliances in " + (variables.name)), ar: ("نسبة الأسر التي تطبّق تعليمات ترشيد استهلاك الطاقة في استخدام الأجهزة الكهربائية في " + (variables.name))},
    spendingEnergyEfficiency: {en: ("Percentage of Households Willing to Spend Money to Replace Old Appliances With Appliances With Higher Energy Efficiency in " + (variables.name)), ar: ("النسبة المئوية للأسر المستعدة لإنفاق الأموال لاستبدال الأجهزة القديمة بأخرى ذات كفاءة أعلى في استخدام الطاقة في " + (variables.name))},
    solarEnergyInterest: {en: ("Percentage of Households that Wish to Use Solar Energy in their Dwellings in " + (variables.name)), ar: ("نسبة الأسر التي ترغب في استخدام الطاقة الشمسية في مساكنها في " + (variables.name))},
  },
  year: {en: "Year", ar: "السنة"},
  percentageOf: {en: "Percentage of Households", ar: "نسبة الأسر"},
  category: {en: "Category", ar: "الفئة"},
  viewData: {
    rationalizeConsumption: {en: "Rationalize electricity consumption", ar: "ترشيد استهلاك الكهرباء"},
    efficiencyPractices: {en: "Energy Efficiency Practices", ar: "ممارسات كفاءة استخدام الطاقة"},
    spendingEnergyEfficiency: {en: "Spending money on new appliances", ar: "الإنفاق من أجل كفاءة الطاقة"},
    solarEnergyInterest: {en: "Solar Energy Interest", ar: "الاهتمام بالطاقة الشمسية"}
  }
}

var cube = selector === "efficiencyPractices" ? "gastat_energy_rationalization_instructions" : selector === "solarEnergyInterest" ? "gastat_photovoltaic_wish" : "households_electricity"

return {
  axisPersist: false,
  data: ((variables.tesseract) + "/data.jsonrecords?Province=" + (variables.id) + "&cube=" + cube + "&drilldowns=Year%2C" + drilldown + "&measures=Percentage&locale=" + locale),
  dataFormat: function (resp) {
    var data = resp.data

    if(selector === "solarEnergyInterest") {
      data.forEach(function (d) {
        d["Solar Energy Response"] = d["Response"],
        d["Solar Energy Response ID"] = d["Response ID"]
      })
    }
    return data
  },
  viewDataFormat: function (resp) {
    var data = resp.data;
    return data.map(function (d) {
      var obj;

      return (( obj = {}, obj[("" + (translations["year"][locale]))] = d.Year, obj[("" + (translations["viewData"][selector][locale]))] = d[drilldown], obj[("" + (translations["percentageOf"][locale]))] = d.Percentage, obj ));
    })
  },
  groupBy: [(groupBy_ + " ID")],
  stacked: true,
  legend: true,
  legendConfig: {
    label: function (d) { return d[drilldown]; }
  },
  tooltipConfig: {
    tbody: [
      [translations["year"][locale], function (d) { return d["Year"]; }],
      [translations["percentageOf"][locale], function (d) { return formatters.pctDecimal(d["Percentage"]); }]
    ]
  },
  type: "BarChart",
  y: "Percentage",
  yConfig: {
    title: ("" + (translations["percentageOf"][locale])),
    tickFormat: function (d) { return formatters.pctChart(d); },
  //  domain: [0, 100]
    rounding: "none"
  },
  x: "Year",
  xConfig: {
    title: years
  },
  title: translations["title"][selector][locale],
  shapeConfig: {
    label: ""
  }
};

var years = variables.years;

var translations = {
  year: {en: "Year", ar: "السنة"},
  pctDwellings: {en: "Percentage of Dwellings", ar: "النسبة المئوية للمساكن"},
  title: {en: ("Percentage of Dwellings Connected to Electricity in " + (variables.name)), ar: ("نسبة المساكن المزوّدة بالكهرباء في " + (variables.name))},
  withSupply: {en: "Dwellings with Electricity Connections", ar: "المساكن المزوّدة بالكهرباء"},
  withoutSupply: {en: "Dwellings without Electricity Connections", ar: "المساكن غير المزوّدة بالكهرباء"},
  province: {en: "Province", ar: "المنطقة"},
  response: {en: "Electricity connected to dwelling (%)", ar: "النسبة المئوية للمساكن المزوّدة بالكهرباء (%)"}
}

return {
  axisPersist: false,
  data: ((variables.tesseract) + "/data.jsonrecords?Province=" + (variables.id) + "&cube=gastat_dwellings_connected_to_electricity&drilldowns=Year%2CProvince,Response&measures=Percentage&locale=" + locale),
//  groupBy: ["Year"],
  dataFormat: function (resp) {
    var data = resp.data

    data.forEach(function (d) {
      d["Electricity Connection Response ID"] = d["Response ID"]
    })

    return data
  },
  viewDataFormat: function (resp) {
    var dataFinal = resp.data.map(function (d) {
      var obj;

      return (( obj = {}, obj[("" + (translations["year"][locale]))] = d["Year"], obj[("" + (translations["province"][locale]))] = d["Province"], obj[("" + (translations["response"][locale]))] = d["Response"], obj[("" + (translations["pctDwellings"][locale]))] = d["Percentage"], obj ));
    })
    return dataFinal
  },
  label: function (d) { return String(d["Response"]); },
  legend: true,
  tooltipConfig: {
    title: function (d) { return d["Response ID"] === 1 ? translations["withSupply"][locale] : translations["withoutSupply"][locale]; },
    tbody: [
      [translations["year"][locale], function (d) { return d["Year"]; }],
      [translations["pctDwellings"][locale], function (d) { return formatters.pctDecimal(d["Percentage"]); }] ]
  },
  groupBy: "Electricity Connection Response ID",
  stacked: true,
  type: "BarChart",
  x: "Year",
 // time: "Year",
  //timeline: false,
  xConfig: {
    title: years
  },
  y: "Percentage",
  yConfig: {
    title: translations["pctDwellings"][locale],
    tickFormat: function (d) { return formatters.pctChart(d); },
    //domain: [0, 100]
    rounding: "none"
  },
  title: translations["title"][locale]
};

var years = variables.years;

var translations = {
  title: {en: ("Percentage of Electricity Sources Used in Dwellings in " + (variables.name)), ar: ("نسب مصادر الكهرباء المستخدمة في المساكن في " + (variables.name))},
  percentage: {en: "Percentage", ar: "النسبة المئوية"},
  pctDwellings: {en: "Percentage of Dwellings", ar: "النسبة المئوية للمساكن"},
  year: {en: "Year", ar: "السنة"},
  electricitySource: {en: "Electricity Source", ar: "مصادر الكهرباء"},
}

return {
  axisPersist: false,
  data: ((variables.tesseract) + "/data.jsonrecords?Province=" + (variables.id) + "&cube=households_electricity&drilldowns=Year%2CElectricity+sources&measures=Percentage&locale=" + locale),
  viewDataFormat: function (resp) {
    var data = resp.data;
    return data.map(function (d) {
      var obj;

      return (( obj = {}, obj[("" + (translations["year"][locale]))] = d.Year, obj[("" + (translations["electricitySource"][locale]))] = d["Electricity sources"], obj[("" + (translations["percentage"][locale]))] = d.Percentage, obj ));
    })
  },
  axisPersist: false,
  groupBy: [
    "Electricity sources ID"
  ],
  label: function (d) { return String(d["Electricity sources"]); },
  type: "BarChart",
  stacked: true,
  tooltipConfig: {
    tbody: [
      [("" + (translations["year"][locale])), function (d) { return d.Year; }],
      [("" + (translations["percentage"][locale])), function (d) { return formatters.pctDecimal(d.Percentage); }] ]
  },
  x: "Year",
  xConfig: {
    title: years
  },
  y: "Percentage",
  yConfig: {
    title: ("" + (translations["pctDwellings"][locale])),
    tickFormat: function (d) { return formatters.pctChart(d); },
    rounding: "none"
  },
  shapeConfig: {
    label: ""
  },
  title: translations["title"][locale]
};

const {tesseract, hierarchy, id, years, billionsOfSar} = variables;

const selector = "consumptionValue" // consumptionValue, quantity
const measure = selector === "consumptionValue" ? "Cost" : "Consumption"

const scaleFactor = 1000000000
const scaleFactorQuantity = 1000000

const translations = {
  titleQuantity: {en: `Quantity of Electrical Energy Consumption in Dwellings in ${variables.name}`, ar: `حجم استهلاك الطاقة الكهربائية في المساكن في ${variables.name}`},
  titleValue: {en: `Value of Electrical Energy Consumption in Dwellings in ${variables.name}`, ar: `قيمة استهلاك الطاقة الكهربائية في المساكن في ${variables.name}`},
  year: {en: "Year", ar: "السنة"},
  quantity: {en: "Million (kWh)", ar: "مليون (كيلوواط ساعة)"},
  value: {en: "Value (SAR)", ar: "القيمة (ريال سعودي)"},
  value_: {en: "Value", ar: "القيمة"},
  period: {en: "Period (Winter/Rest of the Year)", ar: "الفترة (الشتاء/باقي أيام السنة)"},
  valueBillions: {en: "SAR Billions", ar: "مليار ريال سعودي"}
}

return {
  axisPersist: false,
  cache: false,
  data: `${tesseract}/data.jsonrecords?${hierarchy}=${id}&cube=gastat_dwelling_electrical_energy_consumption&drilldowns=Season,Year&measures=Cost,Consumption&locale=${locale}`,
  dataFormat: (resp) => {
    let data = resp.data;
    if (selector === 'consumptionValue') {
      data = data.filter(d => d['Year'] !== 2023)
    }

    data.forEach(d => {
      d["Consumption"] = d["Consumption"] / scaleFactorQuantity
    })
    return data;
  },
  viewDataFormat: (resp) => {
    const data = resp.data;
    if (selector === 'consumptionValue') {
      data = data.filter(d => d['Year'] !== 2023)
    }

    return data.filter(d => d["Cost"] !== 0).map(d => ({
      [`${translations["year"][locale]}`]: d.Year,
      [`${translations["period"][locale]}`]: d["Season"],
      [`${translations["value"][locale]}`]: d["Cost"],
      [`${translations["quantity"][locale]}`]: d["Consumption"],
    }))
  },
  groupBy: ["Season ID"],
  label: d => "",
  legendConfig: {
    label: d => String(d["Season"]),
  },
  legendPosition: "bottom",
  legendTooltip: {
    tbody: false,
  },
  title: selector === "consumptionValue" ? `${translations["titleValue"][locale]}` : `${translations["titleQuantity"][locale]}`,
  tooltipConfig: {
    tbody: [
      [`${translations["year"][locale]}`, d => d["Year"]],
      [`${translations["value_"][locale]}`, d => formatters.sar(d["Cost"])],
      [`${translations["quantity"][locale]}`, d => formatters.commas(d["Consumption"])],
    ]
  },
  type: "BarChart",
  x: "Year",
  xConfig: {
    title: years
  },
  y: measure,
  yConfig: {
    title: selector === "consumptionValue" ? billionsOfSar : `${translations["quantity"][locale]}`,
    tickFormat: selector === "consumptionValue" ? d => formatters.abbreviate(d/scaleFactor) : d => formatters.commas(d)
  }
};

var years = variables.years;

var translations = {
  title: {
    fuelUsed: {en: ("Percentage of Fuel Consumed in Dwellings in " + (variables.name)), ar: ("نسبة الوقود المستهلك في المساكن في " + (variables.name))},
    dwellingsUseGas: {en: ("Percentage of Dwellings That Use Gas (Cooking Gas) in " + (variables.name)), ar: ("نسبة المساكن التي تستخدم غاز الطهي في " + (variables.name))}
  },
  year: {en: "Year", ar: "السنة"},
  fuelType: {en: "Fuel Type", ar: "نوع الوقود"},
  percentage: {en: "Percentage", ar: "النسبة المئوية"},
  province: {en: "Province", ar: "المنطقة"},
}

var selector = "fuelUsed" // fuelUsed, dwellingsUseGas
//const selector = "fuelUsed"

if (selector === "fuelUsed"){

  return {
    axisPersist: false,
    data: ((variables.tesseract) + "/data.jsonrecords?cube=gastat_fuels_consumed&drilldowns=Province%2CFuel+Type%2CYear&measures=Percentage&locale=" + locale + "&include=Province:" + (variables.id)),
    viewDataFormat: function (resp) {
      var data = resp.data;

      return data.map(function (d) {
        var obj;

        return (( obj = {}, obj[("" + (translations["year"][locale]))] = d.Year, obj[("" + (translations["province"][locale]))] = d.Province, obj[("" + (translations["fuelType"][locale]))] = d["Fuel Type"], obj[("" + (translations["percentage"][locale]))] = d.Percentage, obj ));
      })
    },
    groupBy: ["Fuel Type ID"],
    label: function (d) { return String(d["Fuel Type"]); },
    tooltipConfig: {
      tbody: [
        [translations["province"][locale], function (d) { return d["Province"]; }],
        [translations["year"][locale], function (d) { return d["Year"]; }],
        [translations["percentage"][locale], function (d) { return formatters.pctDecimal(d["Percentage"]); }] ]
    },
    type: "BarChart",
    y: "Percentage",
    yConfig: {
      title: translations["percentage"][locale],
      tickFormat: function (d) { return formatters.pctChart(d); },
      //domain: [0, 100]
      rounding: "none"
    },
    //discrete: "x",
    x: "Year",
    xConfig: {
      title: years
    },
   // discrete: "y",
    stacked: true,
    //time: "Year",
  //  timeline: true,
    title: translations["title"][selector][locale],
    shapeConfig: {
      label: ""
    }
  };

}

else {
  return {
    axisPersist: false,
    data: ((variables.tesseract) + "/data.jsonrecords?cube=gastat_cooking_gas_usage&drilldowns=Province%2CYear&measures=Percentage&locale=" + locale + "&include=Province:" + (variables.id)),
    viewDataFormat: function (resp) {
      var data = resp.data;

      return data.map(function (d) {
        var obj;

        return (( obj = {}, obj[("" + (translations["year"][locale]))] = d.Year, obj[("" + (translations["province"][locale]))] = d.Province, obj[("" + (translations["percentage"][locale]))] = d.Percentage, obj ));
      })
    },
    tooltipConfig: {
      title: locale === "en" ? "Dwellings That Use Gas" : "المساكن التي تستخدم الغاز",
      tbody: [
        [translations["province"][locale], function (d) { return d["Province"]; }],
        [translations["year"][locale], function (d) { return d["Year"]; }],
        [translations["percentage"][locale], function (d) { return formatters.pctDecimal(d["Percentage"]); }] ]
    },
    type: "BarChart",
    y: "Percentage",
    yConfig: {
      title: translations["percentage"][locale],
      tickFormat: function (d) { return formatters.pctChart(d); },
   //   domain: [0, 100]
   rounding: "none"
    },
    x: "Year",
    xConfig: {
      title: years
    },
    stacked: true,
    //time: "Year",
  //  timeline: true,
    title: translations["title"][selector][locale],
    shapeConfig: {
      label: ""
    }
  };

}

var years = variables.years;

var translations = {
  title: {
    biomassUse: {en: ("Percentage of Households That Use Biomass Products Inside the Dwellings in " + (variables.name)), ar: ("النسبة المئوية للأسر التي تستخدم منتجات الكتلة الحيوية داخل مساكنها في " + (variables.name))},
    biomassUseByType: {en: ("Percentage of Households That Use Biomass Products Inside the Dwellings by Type of Use in " + (variables.name)), ar: ("النسبة المئوية للأسر التي تستخدم منتجات الكتلة الحيوية داخل مساكنها حسب نوع الاستخدام في " + (variables.name))}
  },
  percentageOf: {en: "Percentage of Households", ar: "نسبة الأسر"},
  useType: {en: "Use Type", ar: "نوع الاستخدام"},
  biomassProduct: {en: "Biomass Products", ar: "منتجات الكتلة الحيوية"},
  useOfBiomass: {en: "Use of Biomass Products", ar: "استخدام منتجات الكتلة الحيوية"},
  percentage: {en: "Percentage", ar: "النسبة المئوية"},
  year: {en: "Year", ar: "السنة"},
  use: {en: "Use of biomass products in dwelling", ar: "استخدام منتجات الكتلة الحيوية في المساكن"},
  province: {en: "Province", ar: "المنطقة"}
}

var selector = "biomassUse" //biomassUse, biomassUseByType

//const selector = 'biomassUse'

if (selector === 'biomassUse'){

  return {
    axisPersist: false,
    data: ((variables.tesseract) + "/data.jsonrecords?Province=" + (variables.id) + "&cube=gastat_biomass_usage&drilldowns=Province%2CYear&measures=Percentage&locale=" + locale),
    viewDataFormat: function (resp) {
      var data = resp.data
      return data.map(function (d) {
        var obj;

        return (( obj = {}, obj[("" + (translations["year"][locale]))] = d.Year, obj[("" + (translations["province"][locale]))] = d.Province, obj[("" + (translations["percentage"][locale]))] = d.Percentage, obj ));
      })
    },
    groupBy: ["Province ID"],
    label: function (d) { return String(d["Province"]); },
    lineLabels: true,
    shapeConfig: {
      Line: {
        label: function label(d) {
          var dataArray = this._filteredData
            	.filter(function (f) { return f["Province ID"] === d["Province ID"]; });
          var maxX = Math.max.apply(Math, dataArray.map(function (f) { return f["Year"]; }));			
          var maxData = dataArray
          	.find(function (f) { return f["Year"] === maxX; });

          return ("" + (formatters.pctDecimal(maxData["Percentage"])));
        },
      }
    },
    tooltipConfig: {
      tbody: [
        [translations["year"][locale], function (d) { return d["Year"]; }],
        [translations["percentage"][locale], function (d) { return formatters.pctDecimal(d["Percentage"]); }]
      ]
    },
    type: "LinePlot",
    x: "Year",
    xConfig: {
      title: years
    },
    y: "Percentage",
    yConfig: {
      title: translations["percentageOf"][locale],
      tickFormat: function (d) { return formatters.pctChart(d); }
    },
    baseline: 0,
    title: translations["title"][selector][locale],
    time: "Year",
    timeline: true,
