  title: {en: ("Percentage Distribution of Individuals with One Severe (or Unable) Disabilities by Type in " + name), ar: ("التوزيع النسبي للأشخاص ذوي الإعاقة الواحدة الشديدة (أو الكلية) في " + name + " حسب النوع")},
  typeOfDisability: {en: "Type of Disability", ar: "نوع الإعاقة"},
  year: {en: "Year", ar: "السنة"},
  relativeShare: {en: "Relative Share (%)", ar: "الحصة النسبية (%)"},
  adminArea: {en: "Administrative Area", ar: "المنطقة الإدارية"},
  1: {en: "Communication disability", ar: "إعاقة في التواصل"},
  2: {en: "Mobility (walking) disability", ar: "إعاقة حركية (في المشي)"},
  3: {en: "Hearing disability", ar: "إعاقة سمعية"},
  4: {en: "Vision disability", ar: "إعاقة بصرية"},
}

return {
  axisPersist: false,
  data: ((variables.tesseract) + "/data.jsonrecords?cube=gstat_disabilities_distribution_one_severe_groups_2_by_type_admin_area&drilldowns=Year,Province&measures=Communication%2CMobility+%28walking%29%2CHearing%2CVision&Province=" + (variables.id) + "&locale=" + locale),
  dataFormat: function (resp) {
    var data = resp.data;
    var transformedData = [];
    
    var disabilityTypes = {
      "Communication": 1,
      "Mobility (walking)": 2,
      "Hearing": 3,
      "Vision": 4
    };
    
    data.forEach(function (item) {
      Object.keys(disabilityTypes).forEach(function (disability) {
        transformedData.push({
          "Year": item.Year,
          "Province ID": item["Province ID"],
          "Province": item.Province,
          "Type of Disability": translations[disabilityTypes[disability]][locale],
          "Type of Disability ID": disabilityTypes[disability],
          "Value": item[disability]
        });
      });
    });

  return transformedData
  },
  viewDataFormat: function (resp) {
    var data = resp.data;
    var transformedData = [];
    
    var disabilityTypes = {
      "Communication": 1,
      "Mobility (walking)": 2,
      "Hearing": 3,
      "Vision": 4
    };
    
    data.forEach(function (item) {
      Object.keys(disabilityTypes).forEach(function (disability) {
        transformedData.push({
          "Year": item.Year,
          "Province ID": item["Province ID"],
          "Province": item.Province,
          "Type of Disability": translations[disabilityTypes[disability]][locale],
          "Type of Disability ID": disabilityTypes[disability],
          "Value": item[disability]
        });
      });
    });

  return transformedData.map(function (d) {
    var obj;

    return (( obj = {}, obj[("" + (translations["year"][locale]))] = d["Year"], obj[("" + (translations["adminArea"][locale]))] = d["Province"], obj[("" + (translations["typeOfDisability"][locale]))] = d["Type of Disability"], obj[("" + (translations["relativeShare"][locale]))] = d["Value"], obj ));
    })
  },
  tooltipConfig: {
    tbody: [
      [translations["year"][locale], function (d) { return d["Year"]; }],
      [translations["relativeShare"][locale], function (d) { return formatters.pctDecimal(d["Value"]); }]
    ]
  },
  groupBy: ["Type of Disability ID"],
  type: "BarChart",
  x: "Value",
  xConfig: {
    title: translations["relativeShare"][locale],
    tickFormat: function (d) { return formatters.pctChart(d); }
  },
  discrete: "y",
  y: "Type of Disability",
  yConfig: {
    title: translations["typeOfDisability"][locale]
  },
  title: translations["title"][locale],
  ySort: function (a, b) { return a["Value"] - b["Value"]; }
};

