const {nest, sum} = libs.d3;
const {tesseract, hierarchy, id} = variables;

const selector = "[[housing]]" //housingType, housingTenure
const selectorName = "{{[[housing]]}}"

const drilldown = selector === "housingType" ? "Housing Type" : "Tenure Type"
const cube = selector === "housingType" ? "gastat_housing_type" : "gastat_housing_tenure"

const dataURL = `${tesseract}/data.jsonrecords?${hierarchy}=${id}&cube=${cube}&drilldowns=Year,${drilldown}&measures=Housing+Units&locale=${locale}`

const scaleFactor = 1000000

const translations = {
  tooltipA: {en: "Year", ar: "السنة"},
  tooltipB: {en: "Housing Units (Million)", ar: "عدد الوحدات السكنية (مليون)"},
  title: {en: `Housing Units (Occupied by Saudi Households) by ${selectorName} in ${variables.name}`, ar: `عدد الوحدات السكنية المأهولة بالأسر السعودية حسب ${selectorName} في ${variables.name}`},
  axis: {en:"Millions", ar: "مليون"},
  year: {en: "Year", ar: "السنة"},
  housingUnits: {en: "Housing Units", ar: "عدد الوحدات السكنية"},
  housingType: {en: "Housing Type", ar: "نوع السكن"}
}

return {
  axisPersist :false,
  cache: false,
  data: dataURL,

  dataFormat: resp => {
    const keyToFilter = selector === "housingType" ? "Housing Type ID" : "Tenure Type ID";
    let data = resp.data.map(d => Object.assign({}, d)).filter(d => d[keyToFilter] !== null && d[keyToFilter] !== undefined);
    nest()
      .key(d => d["Year"])
      .entries(data)
      .forEach(group => {
        const total = sum(group.values, d => d["Housing Units"])
        group.values
          .forEach(d => {
            d["Share"] = (d["Housing Units"] / total) * 100
          })
        });
    return data.filter(d => d["Housing Units"]*1 > 0);
  },

  viewDataFormat: (resp) => {
    const keyToFilter = selector === "housingType" ? "Housing Type ID" : "Tenure Type ID";
    return resp.data.filter(d => d[keyToFilter] !== null && d[keyToFilter] !== undefined).map(d => ({
    [`${translations["year"][locale]}`]: d.Year,
    [`${selectorName}`]: d[drilldown],
    [`${translations["housingUnits"][locale]}`]: d["Housing Units"],
    }))
  },
  discrete: "y",
  groupBy: drilldown,
  label: d => "",
  legend: true,
  legendTooltip: {
    tbody: false,
  },
  title: `${translations["title"][locale]}`,
  tooltipConfig: {
    tbody: [
      [`${translations["tooltipA"][locale]}`, d => d["Year"]],
      [`${translations["tooltipB"][locale]}`, d => formatters.decimal(d["Housing Units"]/scaleFactor)]
    ]
  },
  type: "BarChart",
  time: "Year",
  timeline: true,
  x: "Housing Units",
  xConfig: {
    title: `${translations["tooltipB"][locale]}`,
    tickFormat: d => formatters.abbreviate(d / scaleFactor)
  },
  y: drilldown,
  yConfig: {
    title: selectorName,
  },
  ySort: (a, b) => a["Housing Units"]*1 - b["Housing Units"]*1,
};

