const tradeOption = selector === "imports" ? 1 : 2

let dataURL = `${variables.tesseract}/data.jsonrecords?Trade+Flow=${tradeOption}&cube=gastat_trade_product&drilldowns=Trade+Flow,Section,Month&measures=Million+SAR&parents=true&locale=${locale}`
if(countryForeignTrade){
  dataURL += `Country=${countryForeignTrade["Country ID"]}`
}

const translations = {
  tooltipA: {en: "Month", ar: "الشهر"},
  titleA: {en: "Non-Oil Exports by Products", ar: "الصادرات غير النفطية حسب المنتجات"},
  titleB: {en: "Imports by Products", ar: "الواردات غير النفطية حسب المنتجات"},
  // viewDataFormat translations:
  tradeFlow: {en: "Trade Flow", ar: "تدفق التجارة"},
  section: {en: "Section", ar: "القسم"},
  year: {en: "Year", ar: "السنة"},
  quarter: {en: "Quarter", ar: "الربع"},
  month: {en: "Month", ar: "الشهر"},
  millionSAR: {en: "SAR Million", ar: "مليون ريال"},
  tooltip: {en: `Value (${billionsOfSar})`, ar: `القيمة (${billionsOfSar})`},
}

const scaleFactor = 1000000000

return {
  data: dataURL,
  dataFormat: resp => {
    let data = resp.data.map(d => Object.assign({}, d))
    data.forEach(d => {
      d["Million SAR"] = d["Million SAR"] * 1000000;
      d.Date = `${d.Month.replace("-","/")}/01`;
    });

    nest()
      .key(d => d["Date"])
      .entries(data)
      .forEach(group => {
        const total = sum(group.values, d => d["Million SAR"])
        group.values.forEach(d => {
          d["Share"] = (d["Million SAR"] / total) * 100
        })
      });

    return data;
  },
  viewDataFormat: (resp) => {
    return resp.data.map(d => ({
      [`${translations["year"][locale]}`]: d.Year,
      [`${translations["quarter"][locale]}`]: d.Quarter,
      [`${translations["month"][locale]}`]: d.Month,
      [`${translations["tradeFlow"][locale]}`]: d["Trade Flow"],
      [`${translations["section"][locale]}`]: d.Section,
      [`${translations["millionSAR"][locale]}`]: d["Million SAR"],
    }))
  },
 groupBy: ["Section ID"],
 shapeConfig: {
   Rect: {
    label: (d, i, x) => [
      d["Section"],
      [pctDecimal(d.Share)]
    ],
   }
 },
  label: d => String(d["Section"]),
  legend: true,
  legendPosition: "bottom",
  legendTooltip: {
   title: d => d["Section"],
   tbody: false,
  },
  legendConfig:{
    label: false
  },
  on: {
    click: d => setVariables({productForeignTrade: d, countryForeignTrade: null})
  },
  sum: "Million SAR",
  time: "Date",
  timeline: true,
  timelineConfig: {
    brushing: false
  },
