  tooltipConfig: {
    tbody: [
      [`${translations["tooltipA"][locale]}`, d => d["Month"]],
      [`${translations["tooltip"][locale]}`, d => formatters.decimal(d["Million SAR"]/scaleFactor)]
    ]
  },
  type: "Treemap"
};

