function addMissingYears(data, idCat) {
  const allYears = new Set(data.map(d => d.Year));

  const existingYears = new Set(
    data
      .filter(d => d["Product ID"] === idCat)
      .map(d => d.Year)
  );

  const productName = data.find(d => d["Product ID"] === idCat).Product;

  allYears.forEach(year => {
    if (!existingYears.has(year)) {
      data.push({
        "Product ID": idCat,
        "Product": productName,
        "Year": year,            
        "Thousand Barrels": 0
      });
    }
  });

  return data;
}

