function customSort(a, b) {
      if (a["Real Estate Category ID"] === "A") return 1;
      if (b["Real Estate Category ID"] === "A") return -1;
      return a["Real Estate Category"].localeCompare(b["Real Estate Category"]);
  }

function customYSort(a, b) {
  if (a["Type ID"] == 14) {
    if (b["Type ID"] >= 6) {
      return 1;
    } else {
      return -1;
    }
  }
  return b["Type ID"] - a["Type ID"];
}

