const time = "[[timeBankBranches]]"// yearOption, quarterOption
const timeName = "{{[[timeBankBranches]]}}"
const timeCut = time === "yearOption" ? "Year" : "Quarter"
const timeCutLabel = time === "yearOption" ? "Year" : "Quarter ID"

const translations = {
  title: {en: `Evolution of the Number of Bank Branches in ${name}<br /> <span class="subtitle">(${timeName})</span>`, 
           ar: ` التطوّر في عدد فروع البنوك في ${name} <br /> <span class="subtitle">(${timeName})</span>`},
  quarter: {en: "Quarter", ar: "الربع"},
  year: {en: "Year", ar: "السنة"},
  banks: {en: "Bank Branches", ar: "عدد الفروع"},
}

const timeTooltip = time === "yearOption" ? `${translations["year"][locale]}` : `${translations["quarter"][locale]}`

const dataYear = `${tesseract}/data.jsonrecords?${hierarchy}=${id}&cube=sama_bank_branches&drilldowns=Year,Province&measures=Bank+Branches&locale=${locale}`
const dataQuarter = `${tesseract}/data.jsonrecords?${hierarchy}=${id}&cube=sama_bank_branches&drilldowns=Quarter,Province&measures=Bank+Branches&locale=${locale}`

return {
  data: [dataYear, dataQuarter],
  dataFormat: resp => {
    const dataYear = resp[0].data.map(d => Object.assign({}, d));
    const dataQuarter = resp[1].data.map(d => Object.assign({}, d));
    
    const dataYear_ = dataQuarter.filter(d => d["Quarter ID"].toString().slice(-1) === "4")
    dataYear_.forEach(d => {
      d["Year"] = (d["Quarter ID"].toString().slice(0,4)) * 1
    })
    
    const maxQuarter = libs.d3.max(dataQuarter, d => d["Quarter ID"]).toString().slice(-1)
    const maxYear = libs.d3.max(dataYear_, d => d["Year"])
    //const lastYear = maxQuarter !== 4 ? maxYear - 1 : maxYear
    const dataFinal = time === "yearOption" ? dataYear_.filter(d => d["Year"] <= maxYear) : dataQuarter

    return dataFinal;
  },
  viewDataFormat: (resp) => {
    let dataYear = resp[0].data;
    let dataQuarter = resp[1].data;
    
    let dataYear_ = dataQuarter.filter(d => d["Quarter ID"].toString().slice(-1) === "4")
    dataYear_.forEach(d => {
      d["Year"] = (d["Quarter ID"].toString().slice(0,4)) * 1
    })
    
    const dataFinal = time === "yearOption" ? dataYear_ : dataQuarter
    
    return dataFinal.map(d => ({
      [timeTooltip] : d[timeCut],
      [`${translations["banks"][locale]}`]: d["Bank Branches"],
    }))
  },
  lineLabels: true,
  shapeConfig: {
    Line: {
      label(d) {
        const dataArray = this._filteredData
          	.filter(f => f["Province ID"] === d["Province ID"]);
        const maxX = Math.max(...dataArray.map(f => f[timeCutLabel]));			
        const maxData = dataArray
        	.find(f => f[timeCutLabel] === maxX);
        
        return `${formatters.commas(maxData["Bank Branches"])}`;
      },
    }
  },
  groupBy: ["Province ID"],
  label: d => String(d["Province"]),
  title: `${translations["title"][locale]}`, 
  time: timeCut,
  timeline: true,
  timelineConfig: {
    brushing: true,
    playButton: false
  },
  tooltipConfig: {
    tbody: [
      [timeTooltip, d => formatters.quarterTooltip(d[timeCut])],
      [`${translations["banks"][locale]}`, d => formatters.commas(d["Bank Branches"])]
    ]
  },
  type: "LinePlot",
  x: timeCut,
  xConfig: {
    title: time === "yearOption" ? years : quarters
  },
  y: "Bank Branches",
  yConfig: {
    title: `${translations["banks"][locale]}`,
    tickFormat: d => formatters.commas(d)
  }
};

