function niceValue(value, round, magnitude) {
  return round(value / magnitude) * magnitude;
}

function niceBounds(min, max) {
  const range = max - min;

  // Pick a magnitude one order smaller than the range
  const magnitude = Math.pow(10, Math.floor(Math.log10(range)) - 1);

  const niceMin = niceValue(min, Math.floor, magnitude);
  const niceMax = niceValue(max, Math.ceil, magnitude);

  return [niceMin, niceMax];
}

