const {tesseract, yearRenewableEnergy} = variables;
const {commas, decimal} = formatters;

const translations = {
  year: {en: "Year", ar: "السنة"},
  operation: {en: "Year of Operation Start", ar: "السنة التي بدأ فيها التشغيل"},
  project: {en: "Projects", ar: "المشاريع"},
  title: {en: "Number of Renewable Energy Projects Entering Operation by Year", ar: "عدد مشروعات الطاقة المتجددة التي دخلت حيز التشغيل حسب السنة"},
  tooltip: {en: "Number of projects", ar: "عدد المشروعات"},
};

const dataURL = `${tesseract}/data.jsonrecords?include=${yearRenewableEnergy}:${yearRenewableEnergy}&cube=renewable_energy_projects_all&drilldowns=${yearRenewableEnergy},Renewable+Energy+Project&measures=Operation+Start+Year&locale=${locale}`;

return {
  axisPersist: false,
  cache: false,
  data: dataURL,
  dataFormat: resp => {
    const data = resp.data.map(d => Object.assign({}, d));

    const result = Object.values(
      data.reduce((acc, item) => {
        const year = item["Operation Start Year"];
        const projectName = item["Renewable Energy Project"];

        if (!acc[year]) {
          acc[year] = {
            Year: year,
            "Number of Project": 0,
            Projects: []
          };
        }

        acc[year]["Number of Project"] += 1;
        acc[year].Projects.push(projectName);

        return acc;
      }, {})
    ).map(function(item) {
      return {
        Year: item.Year,
        Measure: "Renewable Energy Project",
        "Number of Project": item["Number of Project"],
        Projects: item.Projects.join(", ")
      };
    });

    return result;
  },
  viewDataFormat: resp => {
    const data = resp.data.map(d => Object.assign({}, d));
    return data.map(d => ({
      [`${translations["operation"][locale]}`]: d["Operation Start Year"],
      [`${translations["project"][locale]}`]: d["Renewable Energy Project"],
    }))
  },  
  groupBy: "Measure",
  label: d => "",
  legend: false,
  shapeConfig: {
    fill: "#6076f8"
  },
  title: `${translations["title"][locale]}`,
  tooltipConfig: {
    tbody: [
     // [`${translations["year"][locale]}`, d => d.Year],
      [`${translations["tooltip"][locale]}`, d => commas(d["Number of Project"])],
      [`${translations["project"][locale]}`, d => (d["Projects"])],
    ],
  },
  type: "BarChart",
  x: "Year",
  xConfig: {
    title: `${translations["operation"][locale]}`,
  },
  y: "Number of Project",
  yConfig: {
    title: `${translations["tooltip"][locale]}`,
    tickFormat: d => commas(d),
  },

}

