const {tesseract, months, sarSymbol} = variables;

const translations = {
  month: {en: "Month", ar: "الشهر"},
  title: {en: "Monthly Evolution of the Earnings per Share", ar: "التطوّر الشهري في ربحية السهم"},
  indicator: {en: "Indicator", ar: "المؤشر"},
  value: {en: `Value (${sarSymbol})`, ar: `القيمة (${sarSymbol})`},
  indName: {en: `Earnings per Share (${sarSymbol})`, ar: `ربحية السهم (${sarSymbol})`},
  yoyGrowth: {en: "YoY Growth", ar: "النمو على أساس سنوي"}
}

return {
  data: `${tesseract}/data.jsonrecords?Indicator=24&cube=tadawul_indicators&drilldowns=Month,Indicator&measures=Value&locale=${locale}`,
  dataFormat: (resp) => {
    let data = resp.data.map(d => Object.assign({}, d));

    data.forEach(d => {
      d["Indicator"] = `${translations["indName"][locale]}`;
      //d["Month Day"] = `${d["Month"].replace(/-/g, "/")}/02`;
      d["Month"] = `${d["Month"]}-01 00:00:00`;
    });
    
    const tempData = data
    
    data.forEach(d => {
      const s = tempData.find(h => (h["Month ID"] * 1  === d["Month ID"] * 1 - 100)) || {};
      d["Value Prev"] = s["Value"];
      d["Value YoY"] = ((d["Value"] - d["Value Prev"]) / d["Value Prev"])*100
    });
    
    return data.filter(d => d["Value"])
  },
  viewDataFormat: (resp) => {
    return resp.data.filter(d => d["Month ID"] >= 201801).map(d => ({
      [`${translations["month"][locale]}`]: d["Month"],
      [`${translations["indicator"][locale]}`]: d.Indicator,
      [`${translations["value"][locale]}`]: d.Value,
    }))
  },
  groupBy: ["Indicator ID"],
  label: d => "",
  lineLabels: true,
  shapeConfig: {
    Line: {
      label(d) {
        const dataArray = this._filteredData
          	.filter(f => f["Indicator ID"] === d["Indicator ID"]);
        const maxX = Math.max(...dataArray.map(f => f["Month ID"] * 1));
        const maxData = dataArray
        	.find(f => f["Month ID"] * 1 === maxX);
        
        return `${formatters.abbreviate(maxData["Value"])}`;
      },
    }
  },
  time: "Month",
  timeline: true,
  timelineConfig: {
    brushing: true,
    playButton: false
  },
  title: `${translations["title"][locale]}`,
  tooltipConfig: {
    title: d => d.Indicator,
    tbody: d => {
      let customTooltip = [];
      
      `${d["Month ID"]}`.slice(0,4) === "2018" ?
        customTooltip = [
          [`${translations["month"][locale]}`, formatters.formatMonth(d["Month ID"])],
          [`${translations["value"][locale]}`, formatters.decimal(d["Value"])],
        ] :
        customTooltip = [
          [`${translations["month"][locale]}`, formatters.formatMonth(d["Month ID"])],
          [`${translations["value"][locale]}`, formatters.decimal(d["Value"])],
          [`${translations["yoyGrowth"][locale]}`, formatters.pctChartDecimal(d["Value YoY"])]
        ]
      return customTooltip;
    },
  },
  type: "LinePlot",
  x: "Month",
  xConfig: {
    title: months
  },
  legend: false,
  y: "Value",
  yConfig: {
    title: `${translations["indName"][locale]}`,
    tickFormat: d => formatters.abbreviate(d)
  }
};

