const {billionsOfSar, quarters} = variables;

const data = `${variables.tesseract}/data.jsonrecords?cube=service_trade_balance&drilldowns=Quarter&measures=Trade+Balance,Exports,Imports&locale=${locale}`

const translations = {
  title: {en: "Quarterly Exports, Imports, and Trade Balance in International Trade in Services", ar: "الصادرات والواردات والميزان التجاري في التجارة الدولية في الخدمات (ربع سنوي)"},
  sarBillion: {en: "SAR Billions", ar: " مليار ريال سعودي" },
  quarter: {en: "Quarter", ar: "الربع"},
  flow: {en: "Flow", ar: "التدفق"},
  value: {en: "Value", ar: "القيمة"},
  tradeBalance: {en: "Trade Balance", ar: "الميزان التجاري"},
  exports: {en: "Exports", ar: "الصادرات"},
  imports: {en: "Imports", ar: "الواردات"},
  tooltip: {en: `Value (${billionsOfSar})`, ar: `القيمة (${billionsOfSar})`},
}

const scaleFactor = 1000000000

return {
  axisPersist: false,
  data: data,
  dataFormat: resp => {
    const data = resp.data;

    let exports_ = data.map(item => ({ Quarter: item.Quarter, Exports: item.Exports, "Quarter ID": item["Quarter ID"] }));
    let imports_ = data.map(item => ({ Quarter: item.Quarter, Imports: item.Imports, "Quarter ID": item["Quarter ID"] }));
    let tradeBalance_ = data.map(item => ({ Quarter: item.Quarter, "Trade Balance": item["Trade Balance"], "Quarter ID": item["Quarter ID"] }));

    const updateData = (data, flow, flowID, value) => {
      data.forEach(d => {
        d["Flow ID"] = flowID;
        d["Flow"] = flow;
        d["Value_"] = flowID === 2 ? d[value] * -1000000 : d[value] * 1000000
        d["Group"] = flowID === 3 ? "Line" : "Bar";  
        delete d[value];
      });
      return data;
    };

    exports_ = updateData(exports_, `${translations["exports"][locale]}`, 1, "Exports");
    imports_ = updateData(imports_, `${translations["imports"][locale]}`, 2, "Imports");
    tradeBalance_ = updateData(tradeBalance_, `${translations["tradeBalance"][locale]}`, 3, "Trade Balance");

    let dataFinal = exports_.concat([...imports_, ...tradeBalance_])

    return dataFinal;
  },
  viewDataFormat: (resp) => {
    const data = resp.data;

    let exports_ = data.map(item => ({ Quarter: item.Quarter, Exports: item.Exports, "Quarter ID": item["Quarter ID"] }));
    let imports_ = data.map(item => ({ Quarter: item.Quarter, Imports: item.Imports, "Quarter ID": item["Quarter ID"] }));
    let tradeBalance_ = data.map(item => ({ Quarter: item.Quarter, "Trade Balance": item["Trade Balance"], "Quarter ID": item["Quarter ID"] }));

    const updateData = (data, flow, flowID, value) => {
      data.forEach(d => {
        d["Flow ID"] = flowID;
        d["Flow"] = flow;
        d["Value_"] = flowID === 2 ? d[value] * -1000000 : d[value] * 1000000
        d["Group"] = flowID === 3 ? "Line" : "Bar";  
        delete d[value];
      });
      return data;
    };

    exports_ = updateData(exports_, `${translations["exports"][locale]}`, 1, "Exports");
    imports_ = updateData(imports_, `${translations["imports"][locale]}`, 2, "Imports");
    tradeBalance_ = updateData(tradeBalance_, `${translations["tradeBalance"][locale]}`, 3, "Trade Balance");

    let dataFinal = exports_.concat([...imports_, ...tradeBalance_])

    return dataFinal.map(d => ({
    [`${translations["quarter"][locale]}`]: d.Quarter,
    [`${translations["flow"][locale]}`]: d.Flow,
    [`${translations["value"][locale]}`]: d.Value_,
    }))
  },
  discrete: "x", 
  groupBy: ["Flow ID"],
  label: d => d["Flow"],
  shape: d => d.Group,
  legendPosition: "bottom",
  legendTooltip: {
    tbody: false,
  },
  stacked: true,
  time: "Quarter",
  timeline: true,
  timelineConfig: {
    brushing: true,
    playButton: false
  },
  tooltipConfig: {
    tbody: [
      [`${translations["quarter"][locale]}`, d => formatters.quarterTooltip(d["Quarter ID"])],
      [`${translations["tooltip"][locale]}`, d => d["Group"] === "Line" ? formatters.decimal(d["Value_"] / scaleFactor) : formatters.decimal(Math.abs(d["Value_"] / scaleFactor))]
    ]
  },
  title: `${translations["title"][locale]}`,
  type: "BarChart",
  x: "Quarter",
  xConfig: {
    title: quarters
  },
  y: "Value_",
  yConfig: {
    title: `${billionsOfSar}`,
    tickFormat: d => formatters.abbreviate(d / scaleFactor)
  }
}

