};

const measureMap = {
  "Index of Consumer Confidence": {
    id: 1,
    key: "generalIndex"
  },
  "Index of Current Economic Conditions": {
    id: 2,
    key: "indexCurrent"
  }
};

function toTidy(data, locale, translations, measureMap) {
  var result = [];

  data.forEach(function(row) {
    Object.keys(measureMap).forEach(function(originalName) {
      var meta = measureMap[originalName];
      var label = translations[meta.key][locale]

      result.push({
        "Month ID": row["Month ID"],
        "Month": row["Month"],
        "Consumer Confidence ID": meta.id, 
        "Consumer Confidence": label,       
        "Value": row[originalName]
      });
    });
  });

  return result;
}

