formatters.logic:
var re = new RegExp(/([\$0-9\,]+)[A-z\-\s\&]*([\$0-9\,]*)/g);
var nums = re.exec(n);
if (nums) {
  nums = nums.slice(1)
    .filter(function (d) { return d.length; })
    .map(function (d) {
      if (d.includes(",")) {
        if (d.indexOf(",") === d.length - 4) {
          d = d
            .replace(/,000$/g, "k")
            .replace(/([0-9]+)(,999$)/g, function (n) { return ((parseInt(n) + 1) + "k"); });
        }
        else if (d.indexOf(",") === d.length - 8) {
          d = d
            .replace(/,000,000$/g, "M")
            .replace(/([0-9]+)(,999,999$)/g, function (n) { return ((parseInt(n) + 1) + "M"); });
        }
      }
      return d;
